baseline.configuration:
worker_processes 1;
events { worker_connections 128; }
http {
    access_log off;
    upstream engines {  server 127.0.0.1:18081 max_conns=1 max_fails=0;
server 127.0.0.1:18082 max_conns=1 max_fails=0; }
    server {
        listen 127.0.0.1:18080;
        client_max_body_size 64k;
        client_body_timeout 10s;
        location = /readyz { return 200 'ready'; }
        location /v1/chat/completions {
            proxy_pass http://engines;
            proxy_http_version 1.1;
            proxy_set_header Connection '';
            proxy_buffering off;
            proxy_request_buffering on;
            proxy_next_upstream off;
            proxy_read_timeout 60s;
            proxy_send_timeout 60s;
            error_page 502 503 =503 @busy;
        }
        location @busy { add_header Retry-After 1 always; return 503; }
    }
}

